[package]
name = "typst-kit"
description = "Common utilities for Typst tooling."
version = { workspace = true }
rust-version = { workspace = true }
authors = { workspace = true }
edition = { workspace = true }
homepage = { workspace = true }
repository = { workspace = true }
license = { workspace = true }
readme = { workspace = true }

[dependencies]
typst-assets = { workspace = true, optional = true }
typst-bundle = { workspace = true, optional = true }
typst-library = { workspace = true }
typst-syntax = { workspace = true }
typst-timing = { workspace = true }
typst-utils = { workspace = true }
chrono = { workspace = true, optional = true }
codespan-reporting = { workspace = true, optional = true }
dirs = { workspace = true, optional = true }
ecow = { workspace = true }
env_proxy = { workspace = true, optional = true }
fastrand = { workspace = true, optional = true }
flate2 = { workspace = true, optional = true }
fontdb = { workspace = true, optional = true }
infer = { workspace = true, optional = true }
native-tls = { workspace = true, optional = true }
notify = { workspace = true, optional = true }
once_cell = { workspace = true }
parking_lot = { workspace = true }
percent-encoding = { workspace = true, optional = true }
rustc-hash = { workspace = true }
same-file = { workspace = true, optional = true }
serde = { workspace = true }
serde_json = { workspace = true }
tar = { workspace = true, optional = true }
tiny_http = { workspace = true, optional = true }
ureq = { workspace = true, optional = true }
url = { workspace = true }

# Explicitly depend on OpenSSL if applicable, so that we can add the
# `openssl/vendored` feature to it if `vendor-openssl` is enabled.
[target.'cfg(not(any(target_os = "windows", target_os = "macos", target_os = "ios", target_os = "watchos", target_os = "tvos")))'.dependencies]
openssl = { workspace = true, optional = true }

[features]
default = []

# Enables functionality related to `typst-bundle`.
bundle = ["dep:typst-bundle"]

# Enables loading of embedded fonts via `fonts::embedded`.
embedded-fonts = ["dep:typst-assets", "typst-assets/fonts"]

# Enables font discovery at paths and from the system via `fonts::scan` and
# `fonts::system`.
scan-fonts = ["dep:fontdb", "fontdb/memmap", "fontdb/fontconfig", "dep:dirs"]

# Enables loading of files from standard locations via `files::SystemFiles`.
system-files = ["system-packages"]

# Enables loading of packages from standard locations via
# `packages::SystemPackages`.
system-packages = ["dep:dirs", "universe-packages"]

# Enables loading of packages from Typst Universe via
# `packages::UniversePackages`.
universe-packages = ["dep:flate2", "dep:tar", "dep:fastrand"]

# Enables obtaining the current date via `datetime::Time::today`.
datetime = ["dep:chrono"]

# Enables emitting terminal-style diagnostics via `diagnostics::emit`.
emit-diagnostics = ["dep:codespan-reporting"]

# Enables network requests via `downloader::SystemDownloader`.
system-downloader = ["dep:env_proxy", "dep:native-tls", "dep:ureq", "dep:openssl"]

# Enables file system watching via `watcher::Watcher`.
watcher = ["dep:notify", "dep:same-file"]

# Enables performance tracing via `timer::Timer`.
timer = []

# Enables live-reloading HTTP serving via `server::HttpServer`.
http-server = ["dep:tiny_http", "dep:infer", "dep:percent-encoding"]

# Whether to vendor OpenSSL for the `system-downloader`. Not applicable to
# Windows and macOS build.
vendor-openssl = ["openssl/vendored"]

[lints]
workspace = true

[package.metadata.docs.rs]
all-features = true
rustdoc-args = ["--cfg", "docsrs"]

//! Typst Kit contains useful building blocks for Typst integrations. It is
//! intended as a single source of truth for things like font searching, package
//! loading and more. In particular, it contains various implementations of
//! functionality used in `typst-cli`.
//!
//! # Features flags
//! Crate functionality that incurs additional dependencies is heavily
//! feature-flagged, so that you can pick exactly what you need. By default, all
//! features are disabled. The available feature flags are:
//!
//! - `bundle`: Enables functionality related to [`typst_bundle`].
//! - `embedded-fonts`: Enables loading of embedded fonts via
//!   [`fonts::embedded`].
//! - `scan-fonts`: Enables font discovery at paths and from the system via
//!   [`fonts::scan`] and [`fonts::system`].
//! - `system-files`: Enables loading of files from standard locations via
//!   [`files::SystemFiles`].
//! - `system-packages`: Enables loading of packages from standard locations via
//!   [`packages::SystemPackages`].
//! - `universe-packages`: Enables loading of packages from Typst Universe via
//!   [`packages::UniversePackages`].
//! - `emit-diagnostics`: Enables emitting terminal-style diagnostics via
//! - `datetime`: Enables obtaining the current date via [`datetime::Time::today`].
//!   [`diagnostics::emit`].
//! - `system-downloader`: Enables network requests via
//!   [`downloader::SystemDownloader`].
//! - `watcher`: Enables file system watching via [`watcher::Watcher`].
//! - `timer`: Enables performance tracing via [`timer::Timer`].
//! - `http-server`: Enables a live-reloading HTTP serving via [`server::HttpServer`].
//! - `vendor-openssl`: Whether to vendor OpenSSL for the `system-downloader`.
//!   Not applicable to Windows and macOS build.

#![cfg_attr(docsrs, feature(doc_cfg))]
#![cfg_attr(
    not(all(
        feature = "bundle",
        feature = "embedded-fonts",
        feature = "scan-fonts",
        feature = "system-files",
        feature = "system-packages",
        feature = "universe-packages",
        feature = "emit-diagnostics",
        feature = "datetime",
        feature = "system-downloader",
        feature = "watcher",
        feature = "timer",
        feature = "http-server",
    )),
    allow(rustdoc::broken_intra_doc_links)
)]

pub mod datetime;
pub mod diagnostics;
pub mod downloader;
pub mod files;
pub mod fonts;
pub mod packages;
pub mod server;
pub mod timer;
pub mod watcher;

