287	impl Tempdir {
288	    /// Creates a directory at the path and auto-cleans it.
289	    fn create(path: PathBuf) -> std::io::Result<Self> {
290	        std::fs::create_dir_all(&path)?;
291	        Ok(Self(path))
292	    }
293	}
