401	        let deps = |store: &mut FileStore<TestLoader>| {
402	            let (_, iter) = store.dependencies();
403	            let mut vec = iter
404	                .map(|id| id.get().vpath().get_without_slash())
405	                .collect::<Vec<_>>();
